/* ============================================
   CreativeHub — Global Styles
   ============================================ */

/* Theme Variables */
:root {
  --brand: #F02D00;
  --brand-dark: #c42500;
  --foreground: #171717;
  --background: #FFFFFF;
  --surface: #F6F6F6;
  --surface-raised: #FFFFFF;
  --muted: #F3F3F3;
  --muted-foreground: #6B7280;
  --border: #E5E5E5;
  --radius: 0.75rem;
  --radius-sm: 0.5rem;
  --shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.05);
  --shadow: 0 1px 3px 0 rgb(0 0 0 / 0.1), 0 1px 2px -1px rgb(0 0 0 / 0.1);
  --shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  --shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1);
  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --transition: 200ms ease-out;
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  color: var(--foreground);
  background: var(--background);
  line-height: 1.6;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  display: block;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

/* Utility classes */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding-left: 1rem;
  padding-right: 1rem;
}

@media (min-width: 768px) {
  .container {
    padding-left: 1.5rem;
    padding-right: 1.5rem;
  }
}

@media (min-width: 1024px) {
  .container {
    padding-left: 2rem;
    padding-right: 2rem;
  }
}

/* ============================================
   HEADER
   ============================================ */
.promo-banner {
  background: var(--foreground);
  color: #fff;
  font-size: 0.875rem;
  padding: 0.5rem 1rem;
  position: relative;
  text-align: center;
}

.promo-banner .countdown {
  color: var(--brand);
  font-weight: 600;
  margin-left: 0.25rem;
}

.promo-banner .close-btn {
  position: absolute;
  right: 0.75rem;
  top: 50%;
  transform: translateY(-50%);
  color: #9CA3AF;
  transition: color var(--transition);
}

.promo-banner .close-btn:hover {
  color: #fff;
}

.site-header {
  background: var(--background);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 50;
}

.site-header .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}

.logo {
  font-size: 1.5rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--foreground);
}

.logo span {
  color: var(--brand);
}

.desktop-nav {
  display: none;
  align-items: center;
  gap: 2rem;
}

.desktop-nav a {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--foreground);
  transition: color var(--transition);
}

.desktop-nav a:hover {
  color: var(--brand);
}

.header-actions {
  display: none;
  align-items: center;
  gap: 0.75rem;
}

.header-actions .btn {
  padding: 0.5rem 1rem;
  border-radius: var(--radius-sm);
  font-size: 0.875rem;
  font-weight: 600;
  transition: all var(--transition);
}

.header-actions .btn-ghost {
  color: var(--foreground);
}

.header-actions .btn-ghost:hover {
  background: var(--muted);
}

.header-actions .btn-primary {
  background: var(--brand);
  color: #fff;
}

.header-actions .btn-primary:hover {
  background: var(--brand-dark);
}

.mobile-menu-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  color: var(--foreground);
}

.mobile-nav {
  display: none;
  position: absolute;
  top: 64px;
  left: 0;
  right: 0;
  background: var(--background);
  border-bottom: 1px solid var(--border);
  padding: 1rem;
  flex-direction: column;
  gap: 0.5rem;
}

.mobile-nav.open {
  display: flex;
}

.mobile-nav a {
  padding: 0.75rem 1rem;
  border-radius: var(--radius-sm);
  font-weight: 500;
  transition: background var(--transition);
}

.mobile-nav a:hover {
  background: var(--muted);
}

@media (min-width: 768px) {
  .desktop-nav,
  .header-actions {
    display: flex;
  }
  .mobile-menu-btn {
    display: none;
  }
}

/* ============================================
   CAROUSEL
   ============================================ */
.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform 300ms ease-out;
}

.carousel-slide {
  flex: 0 0 100%;
  min-width: 100%;
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--background);
  color: var(--foreground);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-md);
  z-index: 10;
  transition: all var(--transition);
}

.carousel-btn:hover {
  background: var(--foreground);
  color: #fff;
}

.carousel-btn.prev { left: 0.5rem; }
.carousel-btn.next { right: 0.5rem; }

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  margin-top: 1rem;
}

.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--border);
  transition: all var(--transition);
}

.carousel-dot.active {
  background: var(--brand);
  width: 24px;
  border-radius: 4px;
}

/* Horizontal scroll carousel (course cards) */
.scroll-carousel {
  position: relative;
}

.scroll-carousel .scroll-track {
  display: flex;
  gap: 1rem;
  overflow-x: auto;
  scroll-behavior: smooth;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding: 0.5rem 0;
}

.scroll-carousel .scroll-track::-webkit-scrollbar {
  display: none;
}

.scroll-carousel .scroll-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--background);
  color: var(--foreground);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-md);
  z-index: 10;
  transition: all var(--transition);
}

.scroll-carousel .scroll-btn:hover {
  background: var(--foreground);
  color: #fff;
}

.scroll-carousel .scroll-btn.prev { left: -20px; }
.scroll-carousel .scroll-btn.next { right: -20px; }

@media (max-width: 767px) {
  .scroll-carousel .scroll-btn {
    display: none;
  }
}

/* ============================================
   CARDS
   ============================================ */
.course-card {
  background: var(--surface-raised);
  border-radius: var(--radius);
  overflow: hidden;
  border: 1px solid var(--border);
  transition: all var(--transition);
  flex: 0 0 260px;
  min-width: 260px;
}

.course-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.course-card .card-image {
  position: relative;
  aspect-ratio: 16 / 10;
  overflow: hidden;
}

.course-card .card-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 300ms ease-out;
}

.course-card:hover .card-image img {
  transform: scale(1.03);
}

.course-card .badge {
  position: absolute;
  top: 0.5rem;
  left: 0.5rem;
  background: var(--brand);
  color: #fff;
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  padding: 0.25rem 0.5rem;
  border-radius: var(--radius-sm);
}

.course-card .card-body {
  padding: 0.875rem;
}

.course-card .card-title {
  font-size: 0.9375rem;
  font-weight: 600;
  line-height: 1.4;
  margin-bottom: 0.25rem;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.course-card .card-meta {
  font-size: 0.8125rem;
  color: var(--muted-foreground);
  margin-bottom: 0.5rem;
}

.course-card .card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.course-card .rating {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  font-size: 0.8125rem;
  font-weight: 600;
}

.course-card .rating .star {
  color: #F59E0B;
}

.course-card .price {
  font-size: 0.9375rem;
  font-weight: 700;
}

.course-card .price .original {
  font-size: 0.75rem;
  color: var(--muted-foreground);
  text-decoration: line-through;
  margin-left: 0.25rem;
  font-weight: 500;
}

/* Specialization card (hero) */
.spec-card {
  background: var(--surface);
  border-radius: var(--radius);
  padding: 2rem;
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.5rem;
  align-items: center;
}

@media (min-width: 768px) {
  .spec-card {
    grid-template-columns: 1fr 1fr;
    padding: 3rem;
  }
}

.spec-card .spec-content h2 {
  font-size: 1.75rem;
  font-weight: 700;
  line-height: 1.2;
  margin-bottom: 0.75rem;
}

.spec-card .spec-content p {
  color: var(--muted-foreground);
  margin-bottom: 1.25rem;
  line-height: 1.6;
}

.spec-card .spec-stats {
  display: flex;
  gap: 1.5rem;
  margin-bottom: 1.5rem;
  flex-wrap: wrap;
}

.spec-card .spec-stat {
  display: flex;
  align-items: center;
  gap: 0.375rem;
  font-size: 0.875rem;
  color: var(--muted-foreground);
}

.spec-card .spec-stat strong {
  color: var(--foreground);
}

.spec-card .spec-pricing {
  display: flex;
  align-items: center;
  gap: 1rem;
  margin-bottom: 1.25rem;
}

.spec-card .spec-pricing .discount-badge {
  background: var(--brand);
  color: #fff;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 0.25rem 0.5rem;
  border-radius: var(--radius-sm);
}

.spec-card .spec-pricing .price-current {
  font-size: 1.5rem;
  font-weight: 800;
}

.spec-card .spec-pricing .price-original {
  font-size: 0.875rem;
  color: var(--muted-foreground);
  text-decoration: line-through;
}

.spec-card .spec-pricing .free-badge {
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--muted-foreground);
}

.spec-card .spec-image {
  border-radius: var(--radius);
  overflow: hidden;
  aspect-ratio: 16 / 10;
}

.spec-card .spec-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* ============================================
   PROJECT CARD
   ============================================ */
.project-card {
  break-inside: avoid;
  margin-bottom: 1rem;
  border-radius: var(--radius);
  overflow: hidden;
  background: var(--surface-raised);
  border: 1px solid var(--border);
  transition: all var(--transition);
}

.project-card:hover {
  box-shadow: var(--shadow-md);
}

.project-card img {
  width: 100%;
  object-fit: cover;
}

.project-card .project-info {
  padding: 0.75rem;
}

.project-card .project-title {
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: 0.25rem;
}

.project-card .project-author {
  font-size: 0.8125rem;
  color: var(--muted-foreground);
  margin-bottom: 0.5rem;
}

.project-card .project-stats {
  display: flex;
  gap: 1rem;
  font-size: 0.75rem;
  color: var(--muted-foreground);
}

.project-card .project-stats span {
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.project-card .winner-badge {
  display: inline-block;
  background: #FEF3C7;
  color: #92400E;
  font-size: 0.6875rem;
  font-weight: 700;
  padding: 0.125rem 0.375rem;
  border-radius: var(--radius-sm);
  margin-left: 0.5rem;
}

/* ============================================
   ACCORDION
   ============================================ */
.accordion-item {
  border-bottom: 1px solid var(--border);
}

.accordion-header {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.25rem 0;
  font-size: 1rem;
  font-weight: 600;
  text-align: left;
  color: var(--foreground);
  transition: color var(--transition);
}

.accordion-header:hover {
  color: var(--brand);
}

.accordion-header .icon {
  transition: transform 200ms ease-out;
  flex-shrink: 0;
}

.accordion-item.open .accordion-header .icon {
  transform: rotate(180deg);
}

.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 300ms ease-out;
}

.accordion-item.open .accordion-body {
  max-height: 500px;
}

.accordion-body p {
  padding-bottom: 1.25rem;
  color: var(--muted-foreground);
  line-height: 1.7;
  font-size: 0.9375rem;
}

/* Footer accordion (mobile) */
.footer-accordion .footer-section {
  border-bottom: 1px solid #333;
}

.footer-accordion .footer-header {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.875rem 0;
  font-size: 0.9375rem;
  font-weight: 600;
  color: #fff;
}

.footer-accordion .footer-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 300ms ease-out;
}

.footer-accordion .footer-section.open .footer-body {
  max-height: 800px;
}

.footer-accordion .footer-body ul {
  padding-bottom: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.footer-accordion .footer-body a {
  color: #9CA3AF;
  font-size: 0.875rem;
  transition: color var(--transition);
}

.footer-accordion .footer-body a:hover {
  color: #fff;
}

/* ============================================
   FOOTER
   ============================================ */
.site-footer {
  background: var(--foreground);
  color: #fff;
  padding-top: 3rem;
  padding-bottom: 2rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 2rem 1.5rem;
}

@media (min-width: 768px) {
  .footer-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (min-width: 1024px) {
  .footer-grid {
    grid-template-columns: repeat(6, 1fr);
  }
}

.footer-col h4 {
  font-size: 0.875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 1rem;
  color: #fff;
}

.footer-col ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.footer-col a {
  color: #9CA3AF;
  font-size: 0.875rem;
  transition: color var(--transition);
}

.footer-col a:hover {
  color: #fff;
}

.footer-bottom {
  margin-top: 3rem;
  padding-top: 2rem;
  border-top: 1px solid #333;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

@media (min-width: 768px) {
  .footer-bottom {
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
  }
}

.footer-apps {
  display: flex;
  gap: 0.75rem;
}

.footer-apps img {
  height: 40px;
}

.footer-legal {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  font-size: 0.8125rem;
  color: #9CA3AF;
}

.footer-legal a:hover {
  color: #fff;
}

.footer-lang {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 1rem;
  font-size: 0.8125rem;
  color: #9CA3AF;
}

.footer-lang a:hover {
  color: #fff;
}

/* Mobile footer accordion override */
@media (max-width: 767px) {
  .footer-grid.desktop {
    display: none;
  }
  .footer-accordion {
    display: block;
  }
}

@media (min-width: 768px) {
  .footer-accordion {
    display: none;
  }
}

/* ============================================
   PRICING
   ============================================ */
.pricing-toggle {
  display: inline-flex;
  background: var(--muted);
  border-radius: 9999px;
  padding: 0.25rem;
  gap: 0.25rem;
}

.pricing-toggle button {
  padding: 0.625rem 1.5rem;
  border-radius: 9999px;
  font-size: 0.9375rem;
  font-weight: 600;
  transition: all var(--transition);
  color: var(--muted-foreground);
}

.pricing-toggle button.active {
  background: var(--foreground);
  color: #fff;
}

.pricing-card {
  background: var(--surface-raised);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 2rem;
  text-align: center;
  transition: all var(--transition);
}

.pricing-card.featured {
  border-color: var(--brand);
  box-shadow: 0 0 0 1px var(--brand);
}

.pricing-card .plan-name {
  font-size: 1.125rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
}

.pricing-card .plan-price {
  font-size: 2.5rem;
  font-weight: 800;
  line-height: 1;
  margin-bottom: 0.25rem;
}

.pricing-card .plan-price span {
  font-size: 1rem;
  font-weight: 500;
  color: var(--muted-foreground);
}

.pricing-card .plan-billing {
  font-size: 0.875rem;
  color: var(--muted-foreground);
  margin-bottom: 1.5rem;
}

.pricing-card .savings-badge {
  display: inline-block;
  background: #DCFCE7;
  color: #166534;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 0.25rem 0.75rem;
  border-radius: 9999px;
  margin-bottom: 1.5rem;
}

.pricing-card .plan-features {
  list-style: none;
  text-align: left;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  margin-bottom: 2rem;
}

.pricing-card .plan-features li {
  display: flex;
  align-items: flex-start;
  gap: 0.5rem;
  font-size: 0.9375rem;
}

.pricing-card .plan-features li .check {
  color: var(--brand);
  flex-shrink: 0;
  margin-top: 0.125rem;
}

.pricing-card .btn-plan {
  width: 100%;
  padding: 0.875rem;
  border-radius: var(--radius-sm);
  font-size: 1rem;
  font-weight: 700;
  transition: all var(--transition);
}

.pricing-card .btn-plan-primary {
  background: var(--brand);
  color: #fff;
}

.pricing-card .btn-plan-primary:hover {
  background: var(--brand-dark);
}

.pricing-card .btn-plan-secondary {
  background: var(--foreground);
  color: #fff;
}

.pricing-card .btn-plan-secondary:hover {
  background: #333;
}

/* ============================================
   LOGIN FORM
   ============================================ */
.login-page {
  min-height: 100vh;
  display: grid;
  grid-template-columns: 1fr;
}

@media (min-width: 768px) {
  .login-page {
    grid-template-columns: 1fr 1fr;
  }
}

.login-panel {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 2rem;
  max-width: 480px;
  margin: 0 auto;
  width: 100%;
}

@media (min-width: 768px) {
  .login-panel {
    padding: 3rem;
  }
}

.login-visual {
  display: none;
  background: var(--foreground);
  position: relative;
  overflow: hidden;
}

@media (min-width: 768px) {
  .login-visual {
    display: flex;
    align-items: center;
    justify-content: center;
  }
}

.login-visual img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0.6;
}

.login-visual .visual-text {
  position: absolute;
  bottom: 3rem;
  left: 3rem;
  right: 3rem;
  color: #fff;
}

.login-visual .visual-text h2 {
  font-size: 2rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
}

.login-visual .visual-text p {
  color: #9CA3AF;
  font-size: 1.125rem;
}

.login-panel h1 {
  font-size: 2rem;
  font-weight: 800;
  margin-bottom: 0.5rem;
}

.login-panel .subtitle {
  color: var(--muted-foreground);
  margin-bottom: 2rem;
}

.social-login {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  margin-bottom: 1.5rem;
}

.social-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  width: 100%;
  padding: 0.75rem;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
  font-size: 0.9375rem;
  font-weight: 600;
  transition: all var(--transition);
}

.social-btn:hover {
  background: var(--muted);
}

.divider {
  display: flex;
  align-items: center;
  gap: 1rem;
  margin-bottom: 1.5rem;
  color: var(--muted-foreground);
  font-size: 0.875rem;
}

.divider::before,
.divider::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--border);
}

.form-group {
  margin-bottom: 1rem;
}

.form-group label {
  display: block;
  font-size: 0.875rem;
